import "server-only";

/**
 * Heebo, the site's own typeface, inlined so the downloaded document renders in
 * it on a machine that has never seen the font and has no network.
 *
 * Heebo is a *variable* font (weight 100–900), so one file per subset covers
 * every weight the page asks for. These are Google's own subset builds, taken
 * from what `next/font/google` downloaded for `src/app/layout.tsx` — the same
 * bytes the site itself serves. Licensed under the SIL Open Font License 1.1;
 * see `OFL.txt` beside this file.
 *
 * Base64 rather than a file read: it needs no `outputFileTracingIncludes`, no
 * `public/` entry and so no matching Dockerfile `COPY` — the three ways this
 * would otherwise work in dev and fail only inside the container.
 *
 * `server-only` because these two strings are ~54KB. They belong in a document
 * rendered on the server, never in the browser bundle.
 *
 * To regenerate: base64 the woff2 for the wanted subset and replace the string.
 */

/** Hebrew subset: U+0590–05FF, U+FB1D–FB4F, plus the shekel sign. */
export const HEEBO_HEBREW_WOFF2_BASE64 =
  "";

/** Latin subset, for the English that turns up inside Hebrew quotes. */
export const HEEBO_LATIN_WOFF2_BASE64 =
  "";
